style.css:
@-moz-document domain("youtube.com") {
/* Your pink theme CSS goes here */
}

@-moz-document domain("youtube.com") {
body {
    background-color: #ffe6f0 !important;
    color: #4a004a !important;
  }

  #container, ytd-app {
    background-color: #fff0f5 !important;
  }

  ytd-masthead, #header {
    background-color: #ff69b4 !important;
  }

  ytd-searchbox {
    background-color: #ffc0cb !important;
    border-radius: 8px;
  }

  ytd-thumbnail {
    border: 2px solid #ffb6c1 !important;
  }

  ytd-video-primary-info-renderer {
    background-color: #fffafc !important;
    color: #800080 !important;
  }

  #progress {
    background-color: #ff1493 !important;
  }
}

@-moz-document domain("youtube.com") {
/* Pinkify the sidebar menu items */
  ytd-guide-entry-renderer a {
    color: #ffb2c5 !important;
  }

  ytd-guide-entry-renderer a:hover {
    background-color: #ffe6f0 !important;
    color: #d6336c !important; /* optional: darker pink on hover */
  }

  /* Optional: make icons pink too */
  ytd-guide-entry-renderer tp-yt-paper-item iron-icon {
    color: #ffb2c5 !important;
  }
}
